#pragma once

// ATen/core/TensorBody.h — SonicBoom M1 hand-authored minimal header.
//
// Upstream, this file is generated by torchgen from
// aten/src/ATen/templates/TensorBody.h and contains the full `at::Tensor`
// class body including every operator method declaration (substituted at the
// `${tensor_method_declarations}` / `${tensor_method_definitions}` markers).
//
// SonicBoom v0 generates only the minimal operator subset (manifest M1), so
// this header carries the Tensor *type* surface — constructors, assignment,
// the borrowed-reference constructor, and the autograd hook declaration —
// plus the handful of operator-method declarations that the compile closure
// (ivalue.h sparse-tensor accessors) actually requires. The operator-method
// *definitions* come from the generated op headers under ATen/ops/.

